import gurobipy as gp
from gurobipy import GRB

# Assume env is provided by runtime
model = gp.Model(env=env)

prep_costs = {'A': 1000, 'B': 920, 'C': 800, 'D': 700}
unit_costs = {'A': 20, 'B': 24, 'C': 16, 'D': 28}
capacities = {'A': 900, 'B': 1000, 'C': 1200, 'D': 1600}
devices = ['A', 'B', 'C', 'D']

y = {}
x = {}
for d in devices:
    y[d] = model.addVar(vtype=GRB.BINARY, name=f"y_{d}")
    x[d] = model.addVar(lb=0, vtype=GRB.INTEGER, name=f"x_{d}")

for d in devices:
    model.addConstr(x[d] <= capacities[d] * y[d], name=f"cap_{d}")

total_expr = gp.quicksum(x[d] for d in devices)
model.addConstr(total_expr >= 2000, name="demand_min")
model.addConstr(total_expr <= 2000, name="demand_max")

obj = gp.quicksum(prep_costs[d] * y[d] + unit_costs[d] * x[d] for d in devices)
model.setObjective(obj, GRB.MINIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
```

